def flush_to_file(force: bool = False):
    """Write current events to JSON and update orphan pulses.

    Optimizations:
    1. Rate limit: at most once every 2 seconds to avoid frequent IO and races.
    2. Atomic write: use safe_write_json to avoid partial reads.
    3. Type fix: default=[] instead of default={}.
    """
    if not force and not _claim_flush_gate():
        return

    try:
        path = _get_output_path()
        orphan_path = _get_orphan_path()

        # Fix: os.path.dirname('file.json') returns '' and os.makedirs('') raises FileNotFoundError.
        # Use abspath before dirname and skip empty dir.
        for file_path in (path, orphan_path):
            output_dir = os.path.dirname(os.path.abspath(file_path))
            if output_dir:
                os.makedirs(output_dir, exist_ok=True)

        with _lock:
            events_snapshot = list(_events)

        safe_write_json(path, events_snapshot[-150:], backup=False)

        new_orphans = _detect_orphans(events_snapshot, min_age=1.5)
        if not isinstance(new_orphans, list):
            new_orphans = []

        existing_orphans = []
        if os.path.exists(orphan_path):
            try:
                existing_orphans = safe_read_json(orphan_path, default=[])
                if not isinstance(existing_orphans, list):
                    existing_orphans = []
            except Exception as e:
                print(f"[WARNING] pulse_tracer.py:128: {type(e).__name__}: {e}")
                existing_orphans = []

        existing_keys = set()
        for orphan in existing_orphans:
            if not isinstance(orphan, dict):
                continue
            key = (orphan.get("timestamp"), orphan.get("organ"), orphan.get("event_type"))
            existing_keys.add(key)

        for orphan in new_orphans:
            if not isinstance(orphan, dict):
                continue
            key = (orphan.get("timestamp"), orphan.get("organ"), orphan.get("event_type"))
            if key not in existing_keys:
                existing_orphans.append(orphan)
                existing_keys.add(key)

        if existing_orphans or os.path.exists(orphan_path):
            safe_write_json(orphan_path, existing_orphans, backup=False)

    except Exception as e:
        print(f"[ERROR] pulse_tracer.py:flush_to_file: {type(e).__name__}: {e}")

