def on_pulse(self, pulse: dict[str, Any]) -> dict[str, Any] | None:
        if not isinstance(pulse, dict):
            self._log(LogLevel.ERROR, f"on_pulse got invalid pulse: {type(pulse).__name__}")
            return None

        raw_event_type = pulse.get("event_type", "")
        event_type = getattr(raw_event_type, "value", raw_event_type)

        payload = pulse.get("payload", {})
        if not isinstance(payload, dict):
            payload = {}

        routes: list[tuple[Any, Any, bool]] = [
            (SystemEvent.BOOT, self._on_system_boot, True),
            (SystemEvent.STOP, self._on_system_stop, True),
            (SystemManagerEvent.HEALTH_CHECK, self._on_health_check, True),
            (SystemManagerEvent.START_SERVICE, self._on_start_service, True),
            (SystemEvent.STATUS_REQUEST, self._on_status_request, False),
            (VascularEvent.ORGAN_ESCALATION, self._on_organ_escalation, True),
        ]

        for event, handler, needs_payload in routes:
            expected = getattr(event, "value", event)
            if event_type != expected:
                continue
            try:
                if needs_payload:
                    return handler(payload)
                return handler()
            except Exception as exc:
                self._log(LogLevel.ERROR, f"on_pulse handler failed for {event_type!r}: {exc}")
                return {"status": "error", "event_type": str(event_type), "error": str(exc)}

        return None

