def safe_write_json(path, data, backup=True, ensure_ascii=False,
                    indent=None, encoding="utf-8", default=None):
    """原子写 JSON: tmp + os.replace, 失败返回 False (不抛异常)。"""
    import tempfile

    _tmp = None
    _fd = None

    def _safe_debug(msg):
        # 日志自身也可能抛异常 (handler 关闭 / 编码错误), 必须隔离
        try:
            _module_logger.debug(msg)
        except Exception:
            pass

    try:
        # D186-A: 备份 I/O 移出路径锁外, 缩短锁持有时间, 缓解写 convoy
        if backup:
            try:
                _keep_backup(path)
            except Exception as _bexc:
                _safe_debug(f"[备份失败] path={path} type={type(_bexc).__name__} {_bexc}")

        _lk = _get_path_lock(path)
        with _lk:
            d = os.path.dirname(path) or "."
            os.makedirs(d, exist_ok=True)
            # 用 mkstemp 生成同目录唯一临时文件: 避免并发同名 tmp 互相覆盖
            _fd, _tmp = tempfile.mkstemp(
                prefix=os.path.basename(path) + ".", suffix=".tmp", dir=d)
            with os.fdopen(_fd, "w", encoding=encoding) as f:
                _fd = None
                json.dump(data, f, ensure_ascii=ensure_ascii,
                          indent=indent, default=default)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except Exception:
                    pass
            _replace_with_retry(_tmp, path)
            _tmp = None
        return True
    except Exception as _exc:
        _safe_debug(f"[写入失败] path={path} type={type(_exc).__name__} {_exc}")
        return False
    finally:
        # 无论成功/失败/日志异常, 都保证 fd 与临时文件不泄漏
        if _fd is not None:
            try:
                os.close(_fd)
            except Exception:
                pass
        if _tmp is not None:
            try:
                if os.path.exists(_tmp):
                    os.remove(_tmp)
            except Exception:
                pass
